#!/usr/bin/env python3
import json,csv,statistics as st,hashlib,datetime
from pathlib import Path
W=Path(__file__).resolve().parent;R=W/'runs'/(W/'RUN_ID').read_text().strip()
def read(name):return list(csv.DictReader((W/'tables'/name).open()))
def f(x,k):return float(x[k])
def sha(p):
 h=hashlib.sha256()
 with p.open('rb') as s:
  for b in iter(lambda:s.read(1048576),b''):h.update(b)
 return h.hexdigest()
a=read('aggregate_ratios.csv');keys=read('key_medians.csv');raw=read('raw_observations.csv');q=read('quality_summary.csv');setup=read('checkpoint_setup.csv');verify=json.loads((W/'verification.json').read_text());assert verify['status']=='PASS'
names=dict(fresh='Fresh',none='Direct',basic='Basic',runnerup='Runner-up')
lines=['# Fairness versus runtime across C0/C1/C2', '', f"Run `{(W/'RUN_ID').read_text().strip()}` | FTF-1D-descriptor-v1 | completed {datetime.datetime.now(datetime.timezone.utc).isoformat()}", '', '**Complete: 180/180 method keys, 135/135 same-budget replay comparisons, 720/720 timing observations. No missing or duplicate keys.** All exact indexed trajectories, integer N/S/SS and retained-population quality agree. Each of 180 gate outputs also agrees with its corresponding accepted T=15 prefix; every measured witness agrees with its gate. Four repeats per key are timing repetitions, not new seeds.','', '**Reporting correction (26 September):** The initial figures and quality summaries mistakenly used saved G (the sum of group-normalized costs) as the worst-group objective. This version uses saved exact Phi throughout. All raw run evidence and timing results are unchanged; see REPORTING_CORRECTION.md.', '', '## Main finding','']
for ds in ['adult','bank','credit']:
 rr=[x for x in a if x['dataset']==ds and x['method']=='none'];rr.sort(key=lambda x:int(x['T']))
 lines.append(f"- **{ds.title()}:** Direct's ratios of total measured algorithm times for C0/C1/C2 are "+' / '.join(f"{f(x,'algorithm_seconds_ratio_total_observed'):.2f}x" for x in rr)+'; E2E ratios are '+' / '.join(f"{f(x,'e2e_seconds_ratio_total_observed'):.2f}x" for x in rr)+'.')
lines+=['', 'Reducing the refinement budget exposes savings from reusing untouched group summaries. At C0, all three replay modes have the same computational path and no certificate attempts; their timing differences do not establish a certificate gain. At positive budgets, both certificate variants reject every attempted certificate and fall back in round zero in all 30 dataset/seed/budget settings per variant. They are slower than Direct throughout and slower than Fresh on Bank. Their remaining Adult/Credit gains over Fresh come from summary reuse despite the fallback overhead. A speedup compares replay and Fresh at the SAME budget. Cross-budget moves also change the learner and its fairness cost.','', '## Design and timing','', 'Frozen Adult/Bank/Credit processed inputs, original partitions and persistent record IDs, k=10, original seeds 10000-10004, and the original independent record batches (30/45/30 deleted records). T=0,1,2; L=6; b=12; preserved clip; gamma=0; no anchor Lloyd. The upstream preprocessing remains fixed and outside the deletion guarantee. Adult/Credit raw provenance gaps remain inherited. No new seed or deletion campaign was added.', '', 'Every setting has its own cache-enabled original-population checkpoint. A four-method correctness pass precedes four separate-process measurement passes. Within each setting, cyclic orders place every method in every execution position once. Each setting holds the shared exclusive OS lock; it releases between batches. All five numerical-library thread limits are one. The same existing Python 3.12.14 / NumPy 2.3.5 environment is reused read-only. Source modules and training map are byte-identical to the corrected baseline.', '', '**Algorithm:** full public method call, including validation, internal encoding/materialization, allocations and instrumentation. Fresh uses build_cache=False. **E2E:** contiguous wall time from opening the input bundle through deletion materialization, checkpoint load for replay, pre-call GC, method call, exact-witness construction and equal-schema JSON output. Receipt metadata, quality scoring and verification are outside the request boundary. Startup is separately measured, with a startup-inclusive table view. No disk cache is flushed and no cold-storage latency is claimed.', '', 'Compared with September19 E2E, this stricter request timer explicitly adds witness construction and pre-call GC and captures small intervening overhead. Quality is computed exactly on gate outputs; repeated outputs are byte/integers-equal and inherit the same quality. Initial cache construction is a separately reported setup cost, never charged to Fresh request time. Encoded data, input arrays, serialized state and per-call allocations remain in their actual measured boundaries.', '', 'Existing T=15 evidence cannot reconstruct these timings because server refinement time is aggregate-only; no time is prorated. The new calls measure cumulative processing through each budget from request start. These curves are budget trajectories, not a proved Pareto frontier or accumulated sequential-deletion service.', '', '## Paired speedups','', 'Ratios are Fresh/method; >1 favors replay. Mean paired ratio and wins use each seed\'s median of four repetitions. Total ratio sums all 20 observations within dataset/T/method. Seed range is the range of five paired median ratios. These are descriptive five-seed results; no repeats-as-IID intervals. The CSV also supplies ratios of total seed medians and the startup-inclusive and idealized-compute views.','', '| Dataset | Budget | Method | Algorithm mean pair | Algorithm total | Seed ratio range | Wins/5 | E2E total | E2E wins/5 |','|---|---:|---|---:|---:|---:|---:|---:|---:|']
for x in a:lines.append(f"| {x['dataset'].title()} | C{x['T']} | {names[x['method']]} | {f(x,'algorithm_seconds_mean_paired_ratio'):.3f} | {f(x,'algorithm_seconds_ratio_total_observed'):.3f} | {f(x,'algorithm_seconds_seed_min'):.3f}-{f(x,'algorithm_seconds_seed_max'):.3f} | {x['algorithm_seconds_wins']} | {f(x,'e2e_seconds_ratio_total_observed'):.3f} | {x['e2e_seconds_wins']} |")
lines+=['', 'Full wins, losses and ties for every timing boundary are in tables/aggregate_ratios.csv. Individual paired ratios and seconds are in tables/paired_seed_ratios.csv.', '', '## Retained-population fairness', '', 'Phi = max(Phi_A, Phi_B) is the maximum group-average squared nearest-center distance on the fixed-point represented survivors. The saved field G = Phi_A + Phi_B is the sum of group-normalized costs; it is not the fairness objective. Tables explicitly label that auxiliary sum as sum_group_normalized_costs. It is identical across methods at each seed/T, including exact rational numerators/denominators. Values below are mean +/- sample SD across five seeds, not confidence intervals.','', '| Dataset | C0 | C1 | C2 | Mean paired C0-to-C2 decrease |','|---|---:|---:|---:|---:|']
for ds in ['adult','bank','credit']:
 qq=sorted((x for x in q if x['dataset']==ds),key=lambda x:int(x['T']));rr=[x for x in keys if x['dataset']==ds and x['method']=='fresh'];drop=[]
 for seed in sorted({x['seed'] for x in rr}):
  z=sorted((x for x in rr if x['seed']==seed),key=lambda x:int(x['T']));assert f(z[2],'Phi')<=f(z[1],'Phi')<=f(z[0],'Phi');drop.append(100*(1-f(z[2],'Phi')/f(z[0],'Phi')))
 lines.append('| '+ds.title()+' | '+' | '.join(f"{f(x,'Phi_mean'):.3f} +/- {f(x,'Phi_sd'):.3f}" for x in qq)+f' | {st.mean(drop):.1f}% (seed range {min(drop):.1f}-{max(drop):.1f}%) |')
lines+=['', 'No policy threshold for acceptable fairness loss was specified. The experiment does not declare C0 or C1 sufficient for an application. Group-average cost does not establish individual, intersectional or downstream fairness.', '', '## Certificate accounting and fallback','', 'N counts eligible retained point-rounds; A attempts, P passes, S passing point-rounds retained after same-round fallback, and J failed assignments repeated in the full fallback rebuild. Attempted pass rate P/A differs from useful coverage S/N; actual assignment point-units are N-S+J. Totals below count each seed once, never multiply by timing repetitions. At T=0 all counters are zero and both rates are undefined.','', '| Dataset | Budget | Method | N | A | P | S | J | P/A | S/N | Fallback seeds/5 |','|---|---:|---|---:|---:|---:|---:|---:|---:|---:|---:|']
for ds in ['adult','bank','credit']:
 for T in [1,2]:
  for m in ['basic','runnerup']:
   z=[x for x in keys if (x['dataset'],x['T'],x['method'])==(ds,str(T),m)];v={k:sum(int(x[k]) for x in z) for k in ['N','A','P','S','J']};fallback=sum(x['abandonment_round'] not in ['','None'] for x in z)
   lines.append(f"| {ds.title()} | C{T} | {names[m]} | {v['N']} | {v['A']} | {v['P']} | {v['S']} | {v['J']} | {v['P']/v['A']:.3%} | {v['S']/v['N']:.3%} | {fallback} |")
lines+=['', 'Raw rows retain failed-assignment, sunk-fallback, rebuild, server, encoding, internal materialization and certificate timers. These timers are nested; do not sum fallback/failed-work columns with client/server totals. tables/component_means.csv reports observed component means. The strict-majority fallback and its duplicated assignments are unchanged.','', '## Repetition noise, setup and background load','']
for ds in ['adult','bank','credit']:
 z=[x for x in keys if x['dataset']==ds]
 lines.append(f"- {ds.title()}: within-key algorithm CV median {st.median(f(x,'algorithm_seconds_cv') for x in z):.2%}, maximum {max(f(x,'algorithm_seconds_cv') for x in z):.2%}; E2E CV median {st.median(f(x,'e2e_seconds_cv') for x in z):.2%}, maximum {max(f(x,'e2e_seconds_cv') for x in z):.2%}. All four observations remain saved.")
starts=[json.loads(p.read_text()) for p in R.glob('*/batch_start.json')];ends=[json.loads(p.read_text()) for p in R.glob('*/batch_end.json')]
loads=[s['load_before']['loadavg'][0] for s in starts]+[s['load_after']['loadavg'][0] for s in ends]
lines+=['',f"The one-minute system load averages at batch boundaries ranged from {min(loads):.2f} to {max(loads):.2f}; all top-process snapshots are retained. Total lock queue time was {sum(s['queue_seconds'] for s in starts):.1f} seconds. The lock coordinates only the two authorized experimental tasks; other desktop processes remain uncontrolled. No dedicated-host claim or causal attribution of small differences is justified.", '', f"Across 45 checkpoints, offline setup wall time totaled {sum(f(x,'setup_seconds') for x in setup):.2f} seconds; cache-enabled algorithm time totaled {sum(f(x,'checkpoint_algorithm_seconds') for x in setup):.2f} seconds. Checkpoint serialized sizes range from {min(int(x['checkpoint_bytes']) for x in setup)/1e6:.2f} to {max(int(x['checkpoint_bytes']) for x in setup)/1e6:.2f} MB. tables/checkpoint_setup.csv gives every setup, serialization and startup cost. The full checkpoint payload includes original data and exact evidence; loading is charged to replay in E2E.", '', '**Idealized parallel-client compute** is stored only as a separate derived estimate: maximum client work per round plus server totals. It omits measured request overhead and all network/secure-aggregation/straggler costs. C0 still requires client group summaries and counts and server initialization; it is not zero communication. There are no real communication measurements, so no deployed speedup or communication guarantee follows.','', '## Scope and reproducibility','', 'Full-grid replay equality uses the same production numerical kernels for Fresh and replay; it is not an independent arithmetic proof. The independently implemented artifact verifier checks indexed bytes, exact integers, source/identity hashes, witness lengths, count conservation and the accepted historical prefixes. The earlier independent arithmetic/oracle gate is referenced as historical lineage, not falsely claimed rerun. The immutable source and unchanged map retain their prior guarantees only within their stated scope.', '', 'No pooling with Task B whole-client deletions, no direct numerical Pan speedup comparison, no locally balanced MERGED adaptation, and no manuscript or Overleaf changes. The reference manuscript is read-only. The three PDF figures are in figures/. PROTOCOL.md contains the frozen plan; CORRECTNESS.md records validation; INTEGRATION_NOTES.md supplies evidence-supported wording only. REPRODUCE.md provides exact commands. All raw witnesses, failed-case slots, source copies and resumable batch receipts stay in this local workspace. No downloads or archive restoration were needed. Local-only files are not automatically backed up by iCloud.']
(W/'REPORT.md').write_text('\n'.join(lines)+'\n')
components=[]
cols=['input_loading_seconds','retained_materialization_seconds','checkpoint_loading_seconds','gc_seconds','algorithm_seconds','witness_construction_seconds','output_serialization_seconds','request_other_seconds','encoding_seconds','internal_materialization_seconds','phase1_client_seconds','phase1_server_seconds','phase2_certify_seconds','phase2_recompute_seconds','phase2_server_seconds','shift_bounds_seconds','algorithm_other_seconds','failed_assignment_seconds','fallback_sunk_seconds','fallback_rebuild_seconds']
for ds in ['adult','bank','credit']:
 for T in range(3):
  for m in names:
   rr=[x for x in raw if (x['dataset'],x['T'],x['method'])==(ds,str(T),m)]
   components.append(dict(dataset=ds,T=T,method=m,observations=len(rr),**{k:st.mean(f(x,k) for x in rr) for k in cols}))
with (W/'tables/component_means.csv').open('w',newline='') as s:
 c=csv.DictWriter(s,fieldnames=list(components[0]));c.writeheader();c.writerows(components)
(W/'CORRECTNESS.md').write_text('''# Correctness record\n\nPASS: 180/180 expected dataset/seed/budget/method keys, no missing or duplicate keys. 135/135 distinct replay-versus-Fresh gate comparisons pass. All 180 gate outputs match accepted T=15 indexed prefixes, and 45 new original-population checkpoint witnesses match their accepted prefixes. All 720 timed outputs match their gate witness exactly; each method occupies each execution position once per setting. Exact quality fractions agree for all 135 gate replay comparisons.\n\nThe independent reporting verifier imports no production training, replay or witness routines. It asserts Phi=max(Phi_A,Phi_B) and G=Phi_A+Phi_B using exact saved rational values for all 180 gate outputs, then derives plotted fairness values from the exact Phi fractions. Raw G is retained only under the explicit table label sum_group_normalized_costs. It parses every saved center byte payload, verifies its shape, finite binary64 values and float.hex encoding; compares the entire indexed C0..CT trajectory, final center and every raw integer N/S/SS; checks array dimensions, nonnegative counts/squared sums and retained-count conservation. It checks source-record identities and deletion mappings against the preserved corrected request, all input SHA256s, all batch-receipt artifact hashes and certificate accounting. Comparison is exact, with no tolerance, permutation, rounded summary or digest-only substitute.\n\nAt T=0 there is exactly one center array (C0, also final) and no refinement-statistic row. Initializer equality is therefore the available trajectory witness; no claim is made that absent refinement statistics were checked. Exact retained-population quality is separately scored. N=A=P=S=J=0; acceptance and coverage rates are undefined.\n\nAll methods use the same surviving records, persistent client IDs, row ordering, frozen transforms, encoding and seed. Source/client identity mapping is checked from the original bundle metadata to each corrected removed_source_records entry and its canonical SHA256. The historical local-index identity warning is not ignored; the paired corrected source identity map is used.\n\nTimings are enabled only after each setting's correctness gate. Every timed witness is checked again. No failed scientific case was observed; no performance-based retry occurred. The reporting checks passed on this run, whereas the September19 oracle/test gate is historical source-bound evidence, not a new execution. Shared-kernel equality and independent arithmetic-oracle validation have distinct scopes. This task does not independently re-prove all numerical arithmetic or preprocessing provenance.\n\nMachine-readable results: verification.json, tables/correctness.csv, per-setting correctness.json and r*_*.verification.json, and complete.json artifact hashes.\n''')
wording=['# Evidence-supported proposed paper wording','','These paragraphs are proposals only; no live manuscript edits were made.','', '> We additionally varied the refinement budget T in {0,1,2} on Adult, Bank and Credit at k=10, retaining the five original P2 seeds and independent record-deletion batches. Across all 180 dataset/seed/budget/method outputs, the 135 replay comparisons matched fresh training at the same budget in the complete available indexed trajectory and exact integer statistics. At T=0 the witness consists of the initialized centers, and there are no refinement statistics or certificate attempts. All methods have exactly the same retained-population worst-group cost Phi=max(Phi_A,Phi_B) at a matched seed and budget.','']
for ds in ['adult','bank','credit']:
 z=sorted((x for x in a if x['dataset']==ds and x['method']=='none'),key=lambda x:int(x['T']))
 wording.append(f"> On {ds.title()}, direct replay's ratios of total measured algorithm times relative to matched-budget fresh training were "+', '.join(f"{f(x,'algorithm_seconds_ratio_total_observed'):.2f}" for x in z)+' at T=0,1,2, respectively; corresponding end-to-end request ratios were '+', '.join(f"{f(x,'e2e_seconds_ratio_total_observed'):.2f}" for x in z)+'. Ratios above one favor replay. Each method was measured four times per seed in balanced order; the repetitions characterize timing variation and are not additional independent seeds.')
wording+=['', '> Lower refinement budgets reduce request computation but produce different learned centers and fairness costs. These plots are budget trajectories rather than a proved Pareto frontier. C0 still requires group-summary/count communication and server initialization. Our measurements are local serial computation and file-I/O latency; network costs are unmeasured. Checkpoint construction is reported separately, and fresh request timing excludes replay-cache construction.', '', 'No claim of a universal speedup, acceptable application-level fairness loss, deployed communication saving, sequential cache service or direct comparability to Pan et al. is supported by this bounded experiment.']
for ds in ['adult','bank','credit']:
 qq=sorted((x for x in q if x['dataset']==ds),key=lambda x:int(x['T']))
 wording.append('')
 wording.append(f"> On {ds.title()}, the mean retained-population worst-group cost Phi was "+', '.join(f"{f(x,'Phi_mean'):.3f}" for x in qq)+' at T=0,1,2, respectively, across the five seeds. These are maxima of group-average costs, not sums of the two group costs.')
(W/'INTEGRATION_NOTES.md').write_text('\n'.join(wording)+'\n')
